const favoriteSources=['yandex','soundcloud','spotify'];let favoriteFilter=localStorage.getItem('soulroom.favoriteFilter')||'all';if(!['all','soulroom',...favoriteSources].includes(favoriteFilter))favoriteFilter='all';
const favoriteGroups=Object.fromEntries(favoriteSources.map(source=>[source,{items:[],loading:false,loaded:false,limit:100,error:'',cached:false}]));
function favoriteItems(){const own=tracks.filter(t=>likes.has(t.id));const list=favoriteFilter==='soulroom'?own:favoriteFilter==='all'?[...own,...favoriteSources.flatMap(s=>favoriteGroups[s].items)]:favoriteGroups[favoriteFilter].items;return [...new Map(list.map(t=>[t.id,t])).values()]}
function favoritesScreen(){const items=favoriteItems(),selected=favoriteFilter==='all'?favoriteSources:favoriteFilter==='soulroom'?[]:[favoriteFilter];return heading('Любимое, отовсюду.',`${items.length} треков · ${favoriteFilter==='all'?'твои источники вместе':favoriteFilter==='soulroom'?'сохранено в soulroom':serviceNames[favoriteFilter]}`)+`<div class="favorite-toolbar"><div class="filters favorite-filters">${[['all','Всё'],['yandex','Яндекс.Музыка'],['soundcloud','SoundCloud'],['spotify','Spotify'],['soulroom','В soulroom']].map(([k,v])=>`<button data-favorite-filter="${k}" class="${favoriteFilter===k?'selected':''}">${v}</button>`).join('')}</div><button class="secondary" id="refreshFavorites" ${!backend||!selected.length?'disabled':''}>Обновить</button></div><div class="favorite-statuses">${selected.map(source=>{const g=favoriteGroups[source];return `<div class="favorite-status ${g.error?'warning':''}"><strong>${serviceNames[source]}</strong><span>${!backend?'Подключи источник в локальном приложении':g.loading?'Загружаем избранное…':g.error?esc(g.error):g.loaded?g.items.length+' треков':''}${g.cached?' · сохранённая копия':''}</span>${g.error||!backend?'<button data-page="connections">Подключить ↗</button>':''}</div>`}).join('')}</div><div id="favoriteTracks">${items.length?items.map(row).join(''):`<div class="empty"><h2>${selected.some(s=>favoriteGroups[s].loading)?'Собираем любимые песни…':'Здесь появится твоя музыка'}</h2><p>${favoriteFilter==='soulroom'?'Сохраняй треки сердцем в soulroom.':'Подключи аккаунты — плеер загрузит их избранное. Локальные сохранения доступны во вкладке «В soulroom».'}</p><button class="primary" data-page="connections">Открыть подключения</button></div>`}</div>${selected.some(s=>favoriteGroups[s].items.length>=favoriteGroups[s].limit&&favoriteGroups[s].limit<300)?'<button class="secondary load-favorites" id="moreFavorites">Загрузить ещё</button>':''}<p class="favorite-footnote">Загружается до 300 последних лайков на источник. Сердце в списке сохраняет трек в soulroom; избранное в сервисах не меняется.</p>`}
async function loadFavoriteSource(source,force=false,more=false){const g=favoriteGroups[source];if(!backend||g.loading||g.loaded&&!force&&!more)return;if(more)g.limit=Math.min(300,g.limit+100);g.loading=true;g.error='';if(page==='favorites')renderFavorites();try{const d=await api(`likes?sources=${source}&limit=${g.limit}`);const result=d.groups?.find(x=>x.source===source);g.items=Array.isArray(result?.items)?result.items:[];g.cached=!!result?.cached;g.error=result?.message||result?.error||'';g.loaded=true}catch(e){g.error=e.message;g.loaded=true}finally{g.loading=false;if(page==='favorites')renderFavorites()}}
function renderFavorites(){if(page==='favorites')$('#view').innerHTML=favoritesScreen()}
const renderBeforeFavorites=render;render=function(){renderBeforeFavorites();if(page==='favorites'){renderFavorites();const requested=favoriteFilter==='all'?favoriteSources:favoriteFilter==='soulroom'?[]:[favoriteFilter];for(const source of requested)loadFavoriteSource(source)}};
const findBeforeFavorites=find;find=function(id){return findBeforeFavorites(id)||favoriteSources.flatMap(s=>favoriteGroups[s].items).find(t=>t.id===id)};
document.addEventListener('click',e=>{if(page!=='favorites')return;const track=e.target.closest('#favoriteTracks [data-track]');if(track&&!e.target.closest('[data-like],[data-track-actions],[data-open-track]')){e.stopImmediatePropagation();queue=favoriteItems();play(find(track.dataset.track))}},true);
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.favoriteFilter){favoriteFilter=b.dataset.favoriteFilter;localStorage.setItem('soulroom.favoriteFilter',favoriteFilter);render()}if(b.id==='refreshFavorites'||b.id==='moreFavorites'){const requested=favoriteFilter==='all'?favoriteSources:favoriteFilter==='soulroom'?[]:[favoriteFilter];for(const source of requested)loadFavoriteSource(source,true,b.id==='moreFavorites')}});
document.addEventListener('backend-ready',()=>{if(page==='favorites')render()});
const connectionsBeforeSpotify=connectionsScreen;connectionsScreen=function(){let html=connectionsBeforeSpotify();const form='<p>Для личных лайков войди с правом чтения библиотеки. Client Secret не нужен.</p><form id="spotifyUserForm"><label for="spotifyUserClient">Client ID приложения Spotify</label><input id="spotifyUserClient" placeholder="Client ID (32 символа)" autocomplete="off" required '+(!backend?'disabled':'')+'><p>Добавь в настройках приложения Spotify адрес возврата: <code>'+esc(backend?location.origin+'/spotify-callback':'http://127.0.0.1:5288/spotify-callback')+'</code></p><button class="primary" '+(!backend?'disabled':'')+'>Войти и загрузить лайки</button></form><p id="spotifyUserNotice" role="status"></p>';html=html.replace('Каталог · поиск версии','Избранное · каталог').replace('Подключи каталог через Client ID и Client Secret. Для прослушивания полного трека найди его версию в Яндексе или SoundCloud.','Войди в аккаунт для загрузки лайков. Для прослушивания полного трека найди его версию в Яндексе или SoundCloud.').replace('<form id="spotifyForm">',form+'<details><summary>Подключить только каталог</summary><form id="spotifyForm">').replace('</form><p id="detail-spotify"','</form></details><p id="detail-spotify"');return html};
let spotifyLoginTimer;
document.addEventListener('submit',async e=>{if(e.target.id!=='spotifyUserForm')return;e.preventDefault();const clientId=$('#spotifyUserClient').value.trim(),notice=$('#spotifyUserNotice'),button=e.target.querySelector('button'),started=Date.now();if(!/^[a-zA-Z0-9]{32}$/.test(clientId))return toast('Client ID должен содержать 32 символа.');button.disabled=true;try{if(window.playerDesktop?.signInSpotify){const d=await window.playerDesktop.signInSpotify(clientId);if(!d.ok)throw Error(d.message||'Не удалось открыть Spotify.');notice.textContent='Заверши вход в открывшемся браузере. После него вернись в soulroom.'}else{const d=await api('spotify/login',{method:'POST',body:JSON.stringify({clientId})});notice.innerHTML=`<a class="primary" href="${esc(d.url)}" target="_blank" rel="noopener">Продолжить в Spotify ↗</a>`}clearInterval(spotifyLoginTimer);spotifyLoginTimer=setInterval(async()=>{if(Date.now()-started>600000){clearInterval(spotifyLoginTimer);return}try{const s=await api('spotify/user-status');if(s.connected&&s.authorizedAt>=started){clearInterval(spotifyLoginTimer);favoriteGroups.spotify.loaded=false;toast('Spotify подключён. Загружаем любимое.');if($('#spotifyUserNotice'))$('#spotifyUserNotice').textContent='Аккаунт Spotify подключён.';loadFavoriteSource('spotify',true);refreshConnections()}}catch{}},2500)}catch(err){notice.textContent=err.message}finally{button.disabled=false}});
window.playerDesktop?.onAuthChanged(data=>{if(favoriteGroups[data.source]){favoriteGroups[data.source].loaded=false;if(page==='favorites')loadFavoriteSource(data.source,true)}});
